import Foundation

// Actual producer schema previewab9bab1c; final protected schema/pin qualification is pending.
enum MissionConceptWire {
    static let schemaData = Data(base64Encoded: "")!
    static let contract = "forge-chat-first-mission/v1"
    static var schema: [String: Any] { try! JSONSerialization.jsonObject(with: schemaData) as! [String: Any] }
    static func validate(_ value: Any, kind: String) throws {
        let definitions = schema["$defs"] as! [String: Any]
        try AdvisoryWire.check(value, definitions[kind] as! [String: Any], definitions: definitions)
    }
    static func resolution(_ data:Data,access:AdvisoryAccess,request:[String:Any]) throws -> MissionResolvedBinding {
        try validate(request,kind:"resolve_request")
        let raw=try AdvisoryWire.object(data);try validate(raw,kind:"resolve_result")
        let binding=raw["binding"] as! [String:Any],scope=binding["scope"] as! [String:Any]
        try AdvisoryWire.scope(scope,access:access)
        let principal=access.forgeInstanceID+":"+access.actorID
        let references=[request["workspace_conversation_id"] as! String,request["workspace_draft_id"] as! String]
        guard raw["operation_id"] as? String==request["operation_id"] as? String,
              binding["principal_reference"] as? String==principal,
              binding["workspace_conversation_id"] as? String==references[0],binding["workspace_draft_id"] as? String==references[1],
              access.conversationIDs.contains(binding["conversation_id"] as! String),
              binding["binding_key"] as? String == (try AdvisoryWire.digest([principal,scope,references[0],references[1]])) else { throw AdvisoryError.invalid }
        return .init(workspaceConversationID:references[0],workspaceDraftID:references[1],producerConversationID:binding["conversation_id"] as! String,bindingKey:binding["binding_key"] as! String)
    }
    static func context(_ data:Data,access:AdvisoryAccess,conversation:String) throws -> MissionFocusedContext {
        let raw=try AdvisoryWire.object(data);try validate(raw,kind:"concept_context")
        let context=raw["context"] as! [String:Any];try AdvisoryWire.scope(context,access:access)
        guard access.conversationIDs.contains(conversation),raw["conversation_id"] as? String==conversation,
              try AdvisoryWire.digest(context)==raw["context_revision"] as? String else { throw AdvisoryError.invalid }
        return .init(context:try AdvisoryWire.decode(context,as:MissionConceptContext.self),revision:raw["context_revision"] as! String)
    }
    static func definition(_ value: Any, allowedDependencies: [String]? = nil) throws -> MissionConceptDefinition {
        try validate(["contract_version": contract, "request_digest": "sha256:" + String(repeating: "0", count: 64), "definition": value], kind: "output")
        let d = try AdvisoryWire.decode(value, as: MissionConceptDefinition.self)
        guard Set(d.dependency_reasons.keys)==Set(d.dependencies),d.dependency_reasons.values.allSatisfy({ $0.trimmingCharacters(in:.whitespacesAndNewlines).count>=20 && AdvisoryWire.safe($0) }) else { throw AdvisoryError.invalid }
        let lists = [d.scope, d.exclusions, d.acceptance_criteria, d.architecture_choices, d.risks, d.dependencies, d.questions]
        guard lists.allSatisfy({ Set($0).count == $0.count }),
              ([d.title, d.objective, d.business_value, d.expected_result, d.change_summary] + lists.flatMap { $0 })
                .allSatisfy({ !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty && AdvisoryWire.safe($0) }),
              allowedDependencies == nil || Set(d.dependencies).isSubset(of: Set(allowedDependencies!)) else { throw AdvisoryError.invalid }
        if d.scope.isEmpty || d.acceptance_criteria.isEmpty || d.acceptance_criteria.contains(where: { $0.trimmingCharacters(in: .whitespacesAndNewlines).count < 20 }) {
            guard !d.questions.isEmpty else { throw AdvisoryError.invalid }
        }
        return d
    }
    static func request(_ raw: Any, access: AdvisoryAccess, conversation: String) throws -> AdvisoryRequest {
        try validate(raw, kind: "request")
        let r = try AdvisoryWire.decode(raw, as: AdvisoryRequest.self)
        try AdvisoryWire.scope(raw as! [String: Any], access: access)
        guard r.conversation_id == conversation, access.conversationIDs.contains(conversation),
              Set(r.selected_sources.map(\.source_id)).count == r.selected_sources.count else { throw AdvisoryError.denied }
        return r
    }
    static func turn(_ raw: Any, access: AdvisoryAccess, conversation: String) throws -> MissionConceptTurnRecord {
        try validate(raw, kind: "turn_record")
        let object = raw as! [String: Any]
        let r = try request(object["request"]!, access: access, conversation: conversation)
        try AdvisoryWire.scope(object["context"] as! [String: Any], access: access)
        let t = try AdvisoryWire.decode(raw, as: MissionConceptTurnRecord.self)
        guard try AdvisoryWire.digest(object["request"]!) == t.request_digest,
              try AdvisoryWire.digest(object["context"]!) == r.context_revision,
              t.context.selected_sources == r.selected_sources else { throw AdvisoryError.invalid }
        if let outcome = t.outcome {
            guard outcome.execution == t.execution else { throw AdvisoryError.invalid }
            if let output = outcome.output {
                let outputRaw = (object["outcome"] as! [String: Any])["output"] as! [String: Any]
                _ = try definition(outputRaw["definition"]!, allowedDependencies: t.context.concept_dependency_references)
                guard output.request_digest == t.request_digest,
                      try AdvisoryWire.digest(outputRaw) == outcome.result_digest else { throw AdvisoryError.invalid }
            }
            if t.status == "COMPLETE" {
                guard outcome.output != nil, outcome.execution == "CONFIRMED", outcome.error_code == nil,
                      outcome.usage_status == "OBSERVED", let usage = outcome.usage,
                      usage.input_tokens <= t.provider.input_token_bound,
                      usage.output_tokens <= t.provider.output_token_bound else { throw AdvisoryError.invalid }
            }
        } else if t.status == "COMPLETE" { throw AdvisoryError.invalid }
        return t
    }
    static func capability(_ data: Data, access: AdvisoryAccess) throws -> AdvisoryCapability {
        let raw = try AdvisoryWire.object(data); try validate(raw, kind: "capability")
        try AdvisoryWire.scope(raw, access: access)
        try AdvisoryWire.scope(raw["context"] as! [String: Any], access: access)
        let cap = try AdvisoryWire.decode(raw, as: AdvisoryCapability.self)
        guard Set(cap.conversation_ids) == Set(access.conversationIDs),
              Set(cap.conversation_ids).count == cap.conversation_ids.count,
              try AdvisoryWire.digest(raw["context"]!) == cap.context_revision else { throw AdvisoryError.invalid }
        return cap
    }
    static func observation(_ data: Data, kind: String, access: AdvisoryAccess, conversation: String, expected: AdvisoryRequest? = nil) throws -> MissionConceptObservation {
        let raw = try AdvisoryWire.object(data); try validate(raw, kind: kind)
        let t = try turn(raw["original_turn"]!, access: access, conversation: conversation)
        let revision = raw["current_revision"] as! Int
        guard expected == nil || t.request == expected!, revision >= t.request.expected_revision + 1 else { throw AdvisoryError.invalid }
        return .init(turn: t, currentRevision: revision)
    }
    static func history(_ data: Data, access: AdvisoryAccess, conversation: String) throws -> MissionConceptHistory {
        let raw = try AdvisoryWire.object(data); try validate(raw, kind: "history")
        try AdvisoryWire.scope(raw["scope"] as! [String: Any], access: access)
        let history = try AdvisoryWire.decode(raw, as: MissionConceptHistory.self)
        guard history.conversation_id == conversation,
              Set(history.turns.map { $0.request.turn_id }).count == history.turns.count else { throw AdvisoryError.invalid }
        for record in raw["turns"] as! [Any] { _ = try turn(record, access: access, conversation: conversation) }
        return history
    }
    static func catalog(_ data: Data, access: AdvisoryAccess, cursor: Int = 0, expectedSnapshot: String? = nil) throws -> MissionConceptCatalog {
        let raw = try AdvisoryWire.object(data); try validate(raw, kind: "catalog")
        try AdvisoryWire.scope(raw["scope"] as! [String: Any], access: access)
        var catalog = try AdvisoryWire.decode(raw, as: MissionConceptCatalog.self)
        guard expectedSnapshot == nil || expectedSnapshot == catalog.snapshot_revision,
              Set(catalog.items.map(\.object_id)).count == catalog.items.count else { throw AdvisoryError.invalid }
        for (item, value) in zip(catalog.items, raw["items"] as! [[String: Any]]) {
            _ = try definition(value["definition"]!)
            guard access.conversationIDs.contains(item.conversation_id), item.revision <= item.conversation_revision,
                  try AdvisoryWire.digest(value["definition"]!) == item.definition_digest,
                  item.title == item.definition.title, item.summary == item.definition.expected_result,
                  item.questions == item.definition.questions else { throw AdvisoryError.invalid }
        }
        guard catalog.next_cursor == nil || catalog.next_cursor == cursor + catalog.items.count else { throw AdvisoryError.invalid }
        if cursor == 0 && catalog.next_cursor == nil {
            guard try AdvisoryWire.digest(raw["items"]!) == catalog.snapshot_revision else { throw AdvisoryError.invalid }
        }
        for item in catalog.items {
            for edge in item.edges {
                guard edge.target_object_id==item.object_id,edge.source_object_id != item.object_id,
                      item.definition.dependencies.contains(edge.candidate_id),item.definition.dependency_reasons[edge.candidate_id]==edge.reason else { throw AdvisoryError.invalid }
            }
        }
        catalog.itemsJSONData = try JSONSerialization.data(withJSONObject:raw["items"]!)
        return catalog
    }
}

struct MissionConceptDefinition: Codable, Equatable, Sendable {
    let title: String; let objective: String; let business_value: String; let expected_result: String
    let scope: [String]; let exclusions: [String]; let acceptance_criteria: [String]
    let architecture_choices: [String]; let risks: [String]; let dependencies: [String]; let questions: [String]
    let change_summary: String; let work_kind: String
    let dependency_reasons: [String:String]
}
struct MissionConceptContext: Codable, Equatable, Sendable {
    let instance_id: String; let project_id: String; let repository_id: String; let dataset_generation: Int
    let included_sources: [String]; let selected_sources: [AdvisorySource]; let missing_sources: [String]
    let freshness: String; let evidence_references: [String]; let limitations: [String]
    let concept_dependency_references: [String]
    let concept_dependency_catalog:[MissionDependencyReference]
}
struct MissionConceptOutput: Codable, Equatable, Sendable {
    let contract_version: String; let request_digest: String; let definition: MissionConceptDefinition
}
struct MissionConceptOutcome: Codable, Equatable, Sendable {
    let execution: String; let diagnostic: AdvisoryDiagnostic; let usage: AdvisoryUsage?; let usage_status: String
    let observed_model: String; let observed_effort: String; let output: MissionConceptOutput?
    let result_digest: String?; let error_code: String?
}
struct MissionConceptTurnRecord: Codable, Equatable, Sendable {
    let request: AdvisoryRequest; let request_digest: String; let session_id: String; let invocation_id: String
    let context: MissionConceptContext; let provider: AdvisoryProvider; let status: String; let lifecycle: [String]
    let execution: String; let outcome: MissionConceptOutcome?; let admitted_at: String; let grant_id: String; let consumption: Int
}
struct MissionConceptObservation: Sendable {
    let turn: MissionConceptTurnRecord; let currentRevision: Int
}
struct MissionConceptHistory: Codable, Equatable, Sendable {
    let contract_version: String; let conversation_id: String; let scope: AdvisoryScope; let revision: Int
    let turns: [MissionConceptTurnRecord]; let next_cursor: Int?; let consumed_turns: Int; let maximum_turns: Int
    let retention: String; let read_only: Bool
}
struct MissionConceptCatalogItem: Codable, Equatable, Sendable {
    let object_id: String; let conversation_id: String; let revision: Int; let conversation_revision: Int
    let definition_digest: String; let definition: MissionConceptDefinition; let source_turn_id: String; let context_revision: String
    let title: String; let summary: String; let state: String; let approval_supported: Bool; let blockers: [String]; let questions: [String]
    let parent_id: String?; let group_id: String?; let labels: [String]; let candidate_id: String?; let mission_id: String?
    let edges:[MissionDependencyEdge]
}
struct MissionConceptCatalog: Codable, Equatable, Sendable {
    let contract_version: String; let scope: AdvisoryScope; let snapshot_revision: String; let items: [MissionConceptCatalogItem]
    let next_cursor: Int?; let population: String; let complete_portfolio: Bool; let read_only: Bool; let additional_model_calls: Int
    var itemsJSONData: Data? = nil
}

struct MissionResolvedBinding:Equatable,Sendable {
    let workspaceConversationID:String
    let workspaceDraftID:String
    let producerConversationID:String
    let bindingKey:String
}

struct MissionDependencyEdge:Codable,Equatable,Sendable {
    let kind:String;let source_object_id:String;let target_object_id:String
    let candidate_id:String;let subject_revision:String;let reason:String;let state:String
}

struct MissionFocusedContext:Sendable { let context:MissionConceptContext;let revision:String }
struct MissionDependencyReference:Codable,Equatable,Sendable {
    let candidate_id:String;let subject_revision:String;let object_id:String;let concept_revision:Int
    let dependencies:[String];let recommendation_status:String;let title:String
}
